schema_ddl:
CREATE TABLE corsi (
    id_corso INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_corso TEXT NOT NULL,
    crediti INT NOT NULL CHECK (crediti BETWEEN 1 AND 30)
);

CREATE TABLE studenti (
    id_studente INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    identificativo_nominativo_primario TEXT NOT NULL,
    cognome TEXT NOT NULL,
    data_nascita DATE NOT NULL,
    id_corso INT REFERENCES corsi(id_corso)
);
